import { isCommercialFilterBaselineValue } from 'components/Filter/utils/commercialSelectOptions';
import type {
  DefaultOptions,
  FilterDataStructure,
  FilterForm,
} from 'models/Filters';

import { isCommercialResultsPortfolioAllowedForGrowthLever } from './commercialResultsCrossFilterRules';
import { COMMERCIAL_RESULTS_CROSS_FILTER_KEYS } from './constants';

function getOptionValues(dimension: DefaultOptions | undefined): string[] {
  if (!dimension?.values) {
    return [];
  }
  return dimension.values
    .map((option) => option?.value)
    .filter(
      (value): value is string => typeof value === 'string' && value !== '',
    );
}

function resolveDefaultForKey(
  key: string,
  defaults: FilterForm,
  dimension: DefaultOptions | undefined,
): FilterForm[string] {
  if (defaults[key] !== undefined) {
    return defaults[key];
  }

  const defaultOption = dimension?.default;
  if (defaultOption?.value !== undefined && defaultOption?.value !== null) {
    return defaultOption.value;
  }

  return 'All';
}

/**
 * Resets V2 draft values that are incompatible with the latest preset cross-filter response.
 */
export function sanitizeCommercialCrossFilterForm(
  form: FilterForm,
  dataFilters: FilterDataStructure,
  defaults: FilterForm,
): FilterForm {
  let changed = false;
  const next = { ...form };

  for (const key of COMMERCIAL_RESULTS_CROSS_FILTER_KEYS) {
    const dimension = dataFilters[key] as DefaultOptions | undefined;
    const current = form[key];

    if (dimension?.enabled === false) {
      const resetValue = resolveDefaultForKey(key, defaults, dimension);
      if (current !== resetValue) {
        next[key] = resetValue;
        changed = true;
      }
      continue;
    }

    if (isCommercialFilterBaselineValue(current)) {
      continue;
    }

    if (
      key === 'portfolios' &&
      !isCommercialResultsPortfolioAllowedForGrowthLever(
        current,
        form.growth_levers,
      )
    ) {
      next[key] = resolveDefaultForKey(key, defaults, dimension);
      changed = true;
      continue;
    }

    const allowedValues = getOptionValues(dimension);
    const currentStr = String(current);
    const isAllowed = allowedValues.some(
      (value) => value.toUpperCase() === currentStr.toUpperCase(),
    );

    if (!isAllowed) {
      next[key] = resolveDefaultForKey(key, defaults, dimension);
      changed = true;
    }
  }

  return changed ? next : form;
}
